BEGIN;
INSERT INTO public.admin_users(id,email,password_hash,role,is_active) VALUES('f8400000-0000-4000-8000-000000000001','newsletter-worker@example.test','test-only','admin',true);
INSERT INTO public.admin_sessions(id,admin_user_id,token_hash) VALUES('f8400000-0000-4000-8000-000000000002','f8400000-0000-4000-8000-000000000001',repeat('1',64));
DO $$ DECLARE actor uuid:='f8400000-0000-4000-8000-000000000001';sid uuid:='f8400000-0000-4000-8000-000000000002';t uuid;s uuid;c uuid;review uuid;j public.delivery_jobs;v jsonb;test uuid;BEGIN
 IF has_function_privilege('authenticated','public.prepare_newsletter_delivery(uuid,uuid,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Browser newsletter preparation';END IF;
 INSERT INTO public.admin_teams(name,slug,created_by) VALUES('Fictional worker scope','fictional-newsletter-worker',actor) RETURNING id INTO t;
 INSERT INTO public.newsletter_subscribers(email,name,team_id,state,is_active,consent_at,confirmed_at) VALUES('fictional-worker-recipient@example.test','Fixture',t,'active',true,now(),now()) RETURNING id INTO s;
 v:=public.mutate_newsletter_record(actor,sid,'campaigns',NULL,'create',NULL,jsonb_build_object('teamId',t,'record',jsonb_build_object('subject','Fictional worker campaign','content','Fixture only','audience','all','recipientIds','[]'::jsonb)),repeat('1',64),repeat('2',64),gen_random_uuid());c:=(v->>'id')::uuid;
 v:=public.create_newsletter_test(actor,sid,c,1,'test-only',repeat('9',64),repeat('2',64),gen_random_uuid());test:=(v->>'testId')::uuid;
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['newsletter_test']) WHERE payload->>'testId'=test::text;
 v:=public.prepare_newsletter_delivery(j.id,j.lease_token,NULL,NULL);
 IF v->>'email'<>'newsletter-worker@example.test' OR NOT(v->>'test')::boolean THEN RAISE EXCEPTION 'Test sent to someone other than requesting account';END IF;
 PERFORM public.finish_newsletter_delivery(j.id,j.lease_token,true,'fictional-test-provider',NULL,false);
 v:=public.review_newsletter_send(actor,sid,c,1,repeat('a',64),gen_random_uuid());review:=(v->>'reviewId')::uuid;
 v:=public.commit_newsletter_send(actor,sid,c,review,repeat('a',64),'test-only','SEND 1',NULL,repeat('3',64),repeat('2',64),gen_random_uuid());PERFORM public.advance_newsletter_campaigns();
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['newsletter_campaign']) WHERE payload->>'campaignId'=c::text;
 IF public.prepare_newsletter_delivery(j.id,gen_random_uuid(),repeat('b',64),repeat('x',100)) IS NOT NULL THEN RAISE EXCEPTION 'Forged delivery lease';END IF;
 v:=public.prepare_newsletter_delivery(j.id,j.lease_token,repeat('b',64),repeat('x',100));
 IF v->>'email'<>'fictional-worker-recipient@example.test' OR v->>'unsubscribeHash'<>repeat('b',64) THEN RAISE EXCEPTION 'Delivery identity / unsubscribe token';END IF;
 v:=public.prepare_newsletter_delivery(j.id,j.lease_token,repeat('c',64),repeat('y',100));
 IF v->>'unsubscribeHash'<>repeat('b',64) OR v->>'secretPayload'<>repeat('x',100) THEN RAISE EXCEPTION 'Retry regenerated message capability';END IF;
 UPDATE public.newsletter_subscribers SET state='unsubscribed' WHERE id=s;
 IF public.prepare_newsletter_delivery(j.id,j.lease_token,repeat('d',64),repeat('z',100)) IS NOT NULL THEN RAISE EXCEPTION 'Unsubscribed recipient sent';END IF;
 IF(SELECT state FROM public.newsletter_campaign_recipients WHERE campaign_id=c)<>'skipped' THEN RAISE EXCEPTION 'Suppression not recorded';END IF;
 PERFORM public.reconcile_newsletter_campaigns();
 IF(SELECT status FROM public.newsletter_campaigns WHERE id=c)<>'sent' OR(SELECT approval_password_hash FROM public.newsletter_campaigns WHERE id=c) IS NOT NULL THEN RAISE EXCEPTION 'Finished campaign retained approval hash';END IF;
 IF EXISTS(SELECT 1 FROM public.claim_worker_jobs(100,ARRAY['newsletter_campaign']) WHERE payload->>'campaignId'=c::text) THEN RAISE EXCEPTION 'Completed campaign requeued';END IF;
END $$;
ROLLBACK;
